import java.awt.*;public class Obstacle{		private int x, y, length, width;		public Obstacle(int this_x, int this_y, int that_x, int that_y){			x = this_x;		y = this_y;		length = that_x - this_x;		width = that_y - this_y;		}	public void draw(Graphics page){		page.setColor (Color.green);			page.fillRect(x, y, length, width);		page.setColor(Color.black);		page.drawString("Obstacle", x, y);	}		public boolean collision(int your_x, int your_y){			int mask_x = your_x + (Robot.MASK);		int mask_y = your_y + (Robot.MASK);		boolean collided = false;				if (mask_x >= x - Robot.MASK)			if (mask_x <= x + length + Robot.MASK)				if (mask_y >= y - Robot.IMAGE)					if (mask_y <= y + width + Robot.IMAGE)						collided = true;		return collided;		}}